def create_bookmark(account_id, collection_id, url, title=None, excerpt=None, tags=None, cover_url=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0490000" if __import__("os").path.isdir("./environment_mix/0490000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    RATE_LIMIT_PER_MINUTE = 30
    URL_MAX_LEN = 2048
    TAGS_MAX = 100

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "_" + "".join(secrets.choice(alphabet) for _ in range(17))

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status="ok", account_id=None, credential_id=None, error_code=None, error_message=None, remote_requests=0):
        logs = _ensure_logs()
        logs.append({
            "id": _gen_id("rdp_req"),
            "endpoint": "create-bookmark",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "status": status,
            "account_id": account_id,
            "credential_id": credential_id,
            "remote_requests": int(remote_requests or 0),
            "error_code": error_code,
            "error_message": error_message,
        })
        _save("request_logs.json", logs)

    def _remote_used_last_min(acct_id):
        logs = _ensure_logs()
        cutoff = now_dt - datetime.timedelta(seconds=60)
        used = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("account_id") != acct_id:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts is None or ts < cutoff:
                continue
            try:
                used += int(r.get("remote_requests") or 0)
            except Exception:
                used += 0
        return used

    def _resolve_active_context_for_account(acct_id):
        accounts = _load("accounts.json")
        creds = _load("api_credentials.json")
        if not isinstance(accounts, list) or not isinstance(creds, list):
            return None, None
        acct = None
        for a in accounts:
            if isinstance(a, dict) and a.get("id") == acct_id:
                acct = a
                break
        if not acct:
            return "NOT_FOUND", None
        if acct.get("status") != "active":
            return "UNAUTHORIZED", None
        for c in creds:
            if not isinstance(c, dict):
                continue
            if c.get("account_id") == acct_id and c.get("status") == "active":
                return acct, c
        return "UNAUTHORIZED", None

    # validate inputs (types and patterns per tool schema, but do not over-reject real IDs from store)
    if not isinstance(account_id, str) or not account_id.strip():
        _log(status="error", error_code="VALIDATION_ERROR", error_message="account_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "account_id must be a non-empty string")
    if not isinstance(collection_id, str) or not collection_id.strip():
        _log(status="error", error_code="VALIDATION_ERROR", error_message="collection_id must be a non-empty string", account_id=account_id)
        return _err("VALIDATION_ERROR", "collection_id must be a non-empty string")
    if not isinstance(url, str):
        _log(status="error", error_code="VALIDATION_ERROR", error_message="url must be a string", account_id=account_id)
        return _err("VALIDATION_ERROR", "url must be a string")
    if url.strip() == "":
        _log(status="error", error_code="VALIDATION_ERROR", error_message="url must be non-empty", account_id=account_id)
        return _err("VALIDATION_ERROR", "url must be non-empty")
    if len(url) > URL_MAX_LEN:
        _log(status="error", error_code="VALIDATION_ERROR", error_message=f"url exceeds maximum length {URL_MAX_LEN}", account_id=account_id)
        return _err("VALIDATION_ERROR", f"url exceeds maximum length {URL_MAX_LEN}")
    if title is not None and not isinstance(title, str):
        _log(status="error", error_code="VALIDATION_ERROR", error_message="title must be a string", account_id=account_id)
        return _err("VALIDATION_ERROR", "title must be a string")
    if excerpt is not None and not isinstance(excerpt, str):
        _log(status="error", error_code="VALIDATION_ERROR", error_message="excerpt must be a string", account_id=account_id)
        return _err("VALIDATION_ERROR", "excerpt must be a string")
    if cover_url is not None and not isinstance(cover_url, str):
        _log(status="error", error_code="VALIDATION_ERROR", error_message="cover_url must be a string", account_id=account_id)
        return _err("VALIDATION_ERROR", "cover_url must be a string")
    if tags is None:
        tags_list = []
    elif isinstance(tags, list):
        tags_list = tags
    else:
        _log(status="error", error_code="VALIDATION_ERROR", error_message="tags must be an array of strings", account_id=account_id)
        return _err("VALIDATION_ERROR", "tags must be an array of strings")
    if len(tags_list) > TAGS_MAX:
        _log(status="error", error_code="VALIDATION_ERROR", error_message=f"too many tags (max {TAGS_MAX})", account_id=account_id)
        return _err("VALIDATION_ERROR", f"too many tags (max {TAGS_MAX})")
    for i, tg in enumerate(tags_list):
        if not isinstance(tg, str):
            _log(status="error", error_code="VALIDATION_ERROR", error_message=f"tags[{i}] must be a string", account_id=account_id)
            return _err("VALIDATION_ERROR", f"tags[{i}] must be a string")

    # relaxed: accept provided ids even if not matching strict pattern, because datastore examples do not match 17-chars constraint
    # but still reject clearly wrong prefixes
    if not account_id.startswith("rdp_acct_"):
        _log(status="error", error_code="VALIDATION_ERROR", error_message="Invalid account_id format", account_id=account_id)
        return _err("VALIDATION_ERROR", "Invalid account_id format")
    if not collection_id.startswith("rdp_col_"):
        _log(status="error", error_code="VALIDATION_ERROR", error_message="Invalid collection_id format", account_id=account_id)
        return _err("VALIDATION_ERROR", "Invalid collection_id format")

    ctx_acct, ctx_cred = _resolve_active_context_for_account(account_id)
    if ctx_acct in ("NOT_FOUND", "UNAUTHORIZED"):
        code = ctx_acct
        _log(status="error", error_code=code, error_message="Account not found" if code == "NOT_FOUND" else "Account not authorized/active credential missing", account_id=account_id)
        return _err(code, "Account not found" if code == "NOT_FOUND" else "Account is not active or lacks an active credential")

    collections = _load("collections.json")
    if not isinstance(collections, list):
        collections = []
    col = None
    for c in collections:
        if isinstance(c, dict) and c.get("id") == collection_id and c.get("account_id") == account_id:
            col = c
            break
    if not col or col.get("status") == "deleted":
        _log(status="error", error_code="NOT_FOUND", error_message="collection not found under account", account_id=account_id, credential_id=ctx_cred.get("id"))
        return _err("NOT_FOUND", "Collection does not exist under that account")

    # create local row first
    bookmarks = _load("bookmarks.json")
    if not isinstance(bookmarks, list):
        bookmarks = []

    search_text = " ".join([x for x in [
        (title or "").strip(),
        (excerpt or "").strip(),
        url.strip(),
        " ".join([t.strip() for t in tags_list if isinstance(t, str)])
    ] if x]).strip() or None

    new_bmk = {
        "id": _gen_id("rdp_bmk"),
        "account_id": account_id,
        "collection_id": collection_id,
        "raindrop_id": None,
        "url": url.strip(),
        "title": title,
        "excerpt": excerpt,
        "tags": tags_list,
        "search_text": search_text,
        "cover_url": cover_url,
        "created_at_remote": None,
        "last_accessed_at_remote": None,
        "status": "creating",
        "error_message": None,
        "synced_at": None,
        "created_at": now,
        "updated_at": now,
    }
    bookmarks.append(new_bmk)
    _save("bookmarks.json", bookmarks)

    # remote create attempt subject to rate limit (simulated remote call)
    remote_used = _remote_used_last_min(account_id)
    remote_allowed = remote_used < RATE_LIMIT_PER_MINUTE
    remote_requests = 0

    if not remote_allowed:
        # remote not attempted; mark error to reflect inability to create remotely
        for b in bookmarks:
            if isinstance(b, dict) and b.get("id") == new_bmk["id"]:
                b["status"] = "error"
                b["error_message"] = "429 rate limited by Raindrop API; retry later"
                b["updated_at"] = now
                break
        _save("bookmarks.json", bookmarks)
        _log(status="error", account_id=account_id, credential_id=ctx_cred.get("id"), error_code="RATE_LIMIT", error_message="Rate limited; remote create not attempted", remote_requests=0)
        return _err("RATE_LIMIT", "Rate limited; remote create not attempted")

    # Simulate success: assign a unique raindrop_id
    existing_raindrop_ids = set()
    for b in bookmarks:
        if isinstance(b, dict) and b.get("account_id") == account_id and b.get("raindrop_id") is not None:
            existing_raindrop_ids.add(b.get("raindrop_id"))
    raindrop_id = None
    # deterministic-ish based on time + randomness while avoiding collisions
    for _ in range(20):
        cand = int(now_dt.timestamp()) * 1000 + secrets.randbelow(1000)
        if cand not in existing_raindrop_ids:
            raindrop_id = cand
            break
    if raindrop_id is None:
        raindrop_id = int(now_dt.timestamp()) * 100000 + secrets.randbelow(100000)

    # enforce unique(account_id, raindrop_id) where not null
    for b in bookmarks:
        if isinstance(b, dict) and b.get("account_id") == account_id and b.get("raindrop_id") == raindrop_id:
            # extremely unlikely; treat as conflict and mark error
            for bb in bookmarks:
                if isinstance(bb, dict) and bb.get("id") == new_bmk["id"]:
                    bb["status"] = "error"
                    bb["error_message"] = "Conflict creating remote raindrop_id"
                    bb["updated_at"] = now
                    break
            _save("bookmarks.json", bookmarks)
            _log(status="error", account_id=account_id, credential_id=ctx_cred.get("id"), error_code="CONFLICT", error_message="Conflict creating bookmark", remote_requests=1)
            return _err("CONFLICT", "Conflict creating bookmark")

    # update to active
    for b in bookmarks:
        if isinstance(b, dict) and b.get("id") == new_bmk["id"]:
            b["raindrop_id"] = raindrop_id
            b["status"] = "active"
            b["created_at_remote"] = now
            b["synced_at"] = now
            b["updated_at"] = now
            b["error_message"] = None
            break
    _save("bookmarks.json", bookmarks)

    # update last_used_at on credential
    creds = _load("api_credentials.json")
    if isinstance(creds, list):
        for c in creds:
            if isinstance(c, dict) and c.get("id") == ctx_cred.get("id"):
                c["last_used_at"] = now
                c["updated_at"] = now
                break
        _save("api_credentials.json", creds)

    remote_requests = 1
    _log(status="ok", account_id=account_id, credential_id=ctx_cred.get("id"), remote_requests=remote_requests)
    # return the stored row (not a fabricated copy different from persisted)
    for b in bookmarks:
        if isinstance(b, dict) and b.get("id") == new_bmk["id"]:
            return {"bookmark": b}
    _log(status="error", account_id=account_id, credential_id=ctx_cred.get("id"), error_code="NOT_FOUND", error_message="bookmark disappeared after create", remote_requests=remote_requests)
    return _err("NOT_FOUND", "Bookmark not found after creation")

def search_bookmarks(account_id, query, collection_id=None, executed_via=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0490000" if __import__("os").path.isdir("./environment_mix/0490000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    RATE_LIMIT_PER_MINUTE = 30

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "_" + "".join(secrets.choice(alphabet) for _ in range(17))

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s[:-1]) if s.endswith("Z") else datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_request_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(endpoint, account_id=None, credential_id=None, status="ok", error_code=None, error_message=None, remote_requests=0):
        logs = _ensure_request_logs()
        logs.append({
            "id": _gen_id("rdp_req"),
            "endpoint": endpoint,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "status": status,
            "account_id": account_id,
            "credential_id": credential_id,
            "remote_requests": int(remote_requests or 0),
            "error_code": error_code,
            "error_message": error_message,
        })
        _save("request_logs.json", logs)

    def _rate_used_last_min(acct_id):
        logs = _ensure_request_logs()
        cutoff = now_dt - datetime.timedelta(seconds=60)
        used = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("account_id") != acct_id:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts is None or ts < cutoff:
                continue
            used += int(r.get("remote_requests") or 0)
        return used

    def _resolve_active_context_for_account(acct_id):
        accounts = _load("accounts.json")
        creds = _load("api_credentials.json")
        if not isinstance(accounts, list) or not isinstance(creds, list):
            return None, None
        acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == acct_id), None)
        if not acct or acct.get("status") != "active":
            return None, None
        cred = next((c for c in creds if isinstance(c, dict) and c.get("account_id") == acct_id and c.get("status") == "active"), None)
        if not cred:
            return None, None
        return acct, cred

    def _b64_decode(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or cur.strip() == "":
            return None
        pad = "=" * ((4 - (len(cur) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    def _b64_encode(obj):
        raw = json.dumps(obj, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _new_search_row(acct_id, q, col_id, via):
        sid = _gen_id("rdp_srch")
        row = {
            "id": sid,
            "account_id": acct_id,
            "query_text": q,
            "collection_id": col_id,
            "executed_via": via,
            "result_count": 0,
            "status": "running",
            "error_message": None,
            "started_at": now,
            "completed_at": None,
            "created_at": now,
            "updated_at": now,
        }
        return row

    try:
        # Validate inputs (NOTE: do NOT enforce the broken regex lengths from tool surface; accept real ids)
        if not isinstance(account_id, str) or not account_id.startswith("rdp_acct_"):
            _log("search-bookmarks", status="error", error_code="VALIDATION_ERROR", error_message="Invalid account_id format")
            return _err("VALIDATION_ERROR", "Invalid account_id format")
        if not isinstance(query, str):
            _log("search-bookmarks", account_id=account_id, status="error", error_code="VALIDATION_ERROR", error_message="query must be a string")
            return _err("VALIDATION_ERROR", "query must be a string")
        if collection_id is not None and (not isinstance(collection_id, str) or not collection_id.startswith("rdp_col_")):
            _log("search-bookmarks", account_id=account_id, status="error", error_code="VALIDATION_ERROR", error_message="Invalid collection_id format")
            return _err("VALIDATION_ERROR", "Invalid collection_id format")
        if executed_via is None:
            executed_via = "local"
        if executed_via not in ("remote", "local", "hybrid"):
            _log("search-bookmarks", account_id=account_id, status="error", error_code="VALIDATION_ERROR", error_message="Invalid executed_via")
            return _err("VALIDATION_ERROR", "Invalid executed_via")
        if limit is None:
            limit = 20
        if not isinstance(limit, int) or limit < 1 or limit > 100:
            _log("search-bookmarks", account_id=account_id, status="error", error_code="VALIDATION_ERROR", error_message="limit out of range")
            return _err("VALIDATION_ERROR", "limit out of range")
        if sort is None:
            sort = "relevance"
        if sort not in ("relevance", "created_at_remote", "last_accessed_at_remote"):
            _log("search-bookmarks", account_id=account_id, status="error", error_code="VALIDATION_ERROR", error_message="Invalid sort")
            return _err("VALIDATION_ERROR", "Invalid sort")
        if order is None:
            order = "desc"
        if order not in ("asc", "desc"):
            _log("search-bookmarks", account_id=account_id, status="error", error_code="VALIDATION_ERROR", error_message="Invalid order")
            return _err("VALIDATION_ERROR", "Invalid order")
        if cursor is not None and (not isinstance(cursor, str) or cursor.strip() == ""):
            _log("search-bookmarks", account_id=account_id, status="error", error_code="VALIDATION_ERROR", error_message="cursor must be a non-empty string")
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string")

        acct, cred = _resolve_active_context_for_account(account_id)
        if not acct or not cred:
            # search-bookmarks must still write search_queries row
            sq = _new_search_row(account_id, query, collection_id, executed_via)
            sq["status"] = "failed"
            sq["error_message"] = "Account not active or missing active credential"
            sq["completed_at"] = now
            sq["updated_at"] = now
            srows = _load("search_queries.json")
            if not isinstance(srows, list):
                srows = []
            srows.append(sq)
            _save("search_queries.json", srows)
            _log("search-bookmarks", account_id=account_id, status="error", error_code="UNAUTHORIZED", error_message=sq["error_message"])
            return _err("UNAUTHORIZED", sq["error_message"], search_query_id=sq["id"])

        # Validate collection belongs to account if provided
        if collection_id is not None:
            cols = _load("collections.json")
            if not isinstance(cols, list):
                cols = []
            col = next((c for c in cols if isinstance(c, dict) and c.get("id") == collection_id and c.get("account_id") == account_id), None)
            if not col:
                sq = _new_search_row(account_id, query, collection_id, executed_via)
                sq["status"] = "failed"
                sq["error_message"] = "collection_id not found for account"
                sq["completed_at"] = now
                sq["updated_at"] = now
                srows = _load("search_queries.json")
                if not isinstance(srows, list):
                    srows = []
                srows.append(sq)
                _save("search_queries.json", srows)
                _log("search-bookmarks", account_id=account_id, credential_id=cred.get("id"), status="error", error_code="NOT_FOUND", error_message=sq["error_message"])
                return _err("NOT_FOUND", sq["error_message"], search_query_id=sq["id"])
            if col.get("status") == "deleted":
                # Treat as not found to avoid returning deleted collection items
                sq = _new_search_row(account_id, query, collection_id, executed_via)
                sq["status"] = "failed"
                sq["error_message"] = "collection is deleted"
                sq["completed_at"] = now
                sq["updated_at"] = now
                srows = _load("search_queries.json")
                if not isinstance(srows, list):
                    srows = []
                srows.append(sq)
                _save("search_queries.json", srows)
                _log("search-bookmarks", account_id=account_id, credential_id=cred.get("id"), status="error", error_code="NOT_FOUND", error_message=sq["error_message"])
                return _err("NOT_FOUND", sq["error_message"], search_query_id=sq["id"])

        # Always write search_queries audit row: running -> completed/failed
        sq_row = _new_search_row(account_id, query, collection_id, executed_via)
        srows = _load("search_queries.json")
        if not isinstance(srows, list):
            srows = []
        srows.append(sq_row)
        _save("search_queries.json", srows)

        remote_requests = 0
        # Enforce rate limiting for remote/hybrid
        if executed_via in ("remote", "hybrid"):
            used = _rate_used_last_min(account_id)
            if used + 1 > RATE_LIMIT_PER_MINUTE:
                # If hybrid, fall back to local; if remote, fail
                if executed_via == "remote":
                    sq_row["status"] = "failed"
                    sq_row["error_message"] = "Rate limit exceeded"
                    sq_row["completed_at"] = now
                    sq_row["updated_at"] = now
                    # persist update
                    srows = _load("search_queries.json")
                    if isinstance(srows, list):
                        for i, r in enumerate(srows):
                            if isinstance(r, dict) and r.get("id") == sq_row["id"]:
                                srows[i] = sq_row
                                break
                        _save("search_queries.json", srows)
                    _log("search-bookmarks", account_id=account_id, credential_id=cred.get("id"), status="error", error_code="RATE_LIMIT", error_message="Rate limit exceeded")
                    return _err("RATE_LIMIT", "Rate limit exceeded", search_query_id=sq_row["id"])
                executed_via_effective = "local"
            else:
                executed_via_effective = executed_via
                remote_requests = 1
        else:
            executed_via_effective = "local"

        # Local search in bookmarks.search_text
        bmarks = _load("bookmarks.json")
        if not isinstance(bmarks, list):
            bmarks = []
        q = query.strip().lower()
        results = []
        for b in bmarks:
            if not isinstance(b, dict):
                continue
            if b.get("account_id") != account_id:
                continue
            if b.get("status") == "deleted":
                continue
            if collection_id is not None and b.get("collection_id") != collection_id:
                continue
            hay = b.get("search_text")
            if not isinstance(hay, str) or hay == "":
                # fallback to url/title/excerpt/tags
                parts = []
                for k in ("title", "excerpt", "url"):
                    v = b.get(k)
                    if isinstance(v, str) and v:
                        parts.append(v)
                tgs = b.get("tags")
                if isinstance(tgs, list):
                    parts.extend([t for t in tgs if isinstance(t, str)])
                hay = " ".join(parts)
            if q == "" or (isinstance(hay, str) and q in hay.lower()):
                results.append(b)

        # sorting
        def _key_relevance(b):
            hay = b.get("search_text")
            if not isinstance(hay, str) or not q:
                return 999999
            idx = hay.lower().find(q)
            return idx if idx >= 0 else 999999

        def _key_dt(b, field):
            d = _parse_dt(b.get(field))
            return d or datetime.datetime(1970, 1, 1)

        if sort == "relevance":
            results.sort(key=_key_relevance, reverse=(order == "desc"))
        elif sort == "created_at_remote":
            results.sort(key=lambda b: _key_dt(b, "created_at_remote"), reverse=(order == "desc"))
        else:
            results.sort(key=lambda b: _key_dt(b, "last_accessed_at_remote"), reverse=(order == "desc"))

        # cursor pagination (opaque but supports legacy callers who passed non-b64 strings)
        start_idx = 0
        if cursor:
            decoded = _b64_decode(cursor)
            if isinstance(decoded, dict) and decoded.get("i") is not None:
                try:
                    start_idx = int(decoded.get("i"))
                except Exception:
                    start_idx = 0
            else:
                # tolerate cursor being an arbitrary string (audit shows this happens)
                start_idx = 0

        page = results[start_idx:start_idx + limit]
        next_idx = start_idx + len(page)
        has_more = next_idx < len(results)
        next_cursor = _b64_encode({"i": next_idx}) if has_more else None

        # finalize search query row
        sq_row["executed_via"] = executed_via_effective if executed_via_effective in ("remote", "local", "hybrid") else "local"
        sq_row["result_count"] = len(page)
        sq_row["status"] = "completed"
        sq_row["completed_at"] = now
        sq_row["updated_at"] = now
        srows = _load("search_queries.json")
        if isinstance(srows, list):
            for i, r in enumerate(srows):
                if isinstance(r, dict) and r.get("id") == sq_row["id"]:
                    srows[i] = sq_row
                    break
            _save("search_queries.json", srows)

        # touch credential last_used_at
        creds = _load("api_credentials.json")
        if isinstance(creds, list):
            for c in creds:
                if isinstance(c, dict) and c.get("id") == cred.get("id"):
                    c["last_used_at"] = now
                    c["updated_at"] = now
                    break
            _save("api_credentials.json", creds)

        _log("search-bookmarks", account_id=account_id, credential_id=cred.get("id"), status="ok", remote_requests=remote_requests)
        return {
            "search_query": sq_row,
            "bookmarks": page,
            "page": {
                "limit": limit,
                "cursor": cursor,
                "next_cursor": next_cursor,
                "has_more": has_more,
                "total": len(results),
            },
        }
    except Exception as e:
        # ensure we still log a request; and do best-effort to write a failed search row if possible
        try:
            sq_row = {
                "id": _gen_id("rdp_srch"),
                "account_id": account_id if isinstance(account_id, str) else None,
                "query_text": query if isinstance(query, str) else None,
                "collection_id": collection_id if isinstance(collection_id, str) else None,
                "executed_via": executed_via if executed_via in ("remote", "local", "hybrid") else "local",
                "result_count": 0,
                "status": "failed",
                "error_message": str(e),
                "started_at": now,
                "completed_at": now,
                "created_at": now,
                "updated_at": now,
            }
            srows = _load("search_queries.json")
            if not isinstance(srows, list):
                srows = []
            srows.append(sq_row)
            _save("search_queries.json", srows)
        except Exception:
            sq_row = None
        _log("search-bookmarks", account_id=account_id if isinstance(account_id, str) else None, status="error", error_code="CONFLICT", error_message=str(e))
        return _err("CONFLICT", "Unexpected error", detail=str(e), search_query_id=(sq_row.get("id") if isinstance(sq_row, dict) else None))

def list_collections(account_id, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0490000" if __import__("os").path.isdir("./environment_mix/0490000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    RATE_LIMIT_PER_MINUTE = 30
    SYNC_TTL_SECONDS = 3600

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "_" + "".join(secrets.choice(alphabet) for _ in range(17))

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s[:-1]) if s.endswith("Z") else datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_request_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(endpoint, account_id=None, credential_id=None, status_s="ok", error_code=None, error_message=None, remote_requests=0):
        logs = _ensure_request_logs()
        logs.append({
            "id": _gen_id("rdp_req"),
            "endpoint": endpoint,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "status": status_s,
            "account_id": account_id,
            "credential_id": credential_id,
            "remote_requests": int(remote_requests or 0),
            "error_code": error_code,
            "error_message": error_message,
        })
        _save("request_logs.json", logs)

    def _rate_used_last_min(acct_id):
        logs = _ensure_request_logs()
        cutoff = now_dt - datetime.timedelta(seconds=60)
        used = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("account_id") != acct_id:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts is None or ts < cutoff:
                continue
            used += int(r.get("remote_requests") or 0)
        return used

    def _resolve_active_context_for_account(acct_id):
        accounts = _load("accounts.json")
        creds = _load("api_credentials.json")
        if not isinstance(accounts, list) or not isinstance(creds, list):
            return None, None
        acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == acct_id), None)
        if not acct or acct.get("status") != "active":
            return None, None
        cred = next((c for c in creds if isinstance(c, dict) and c.get("account_id") == acct_id and c.get("status") == "active"), None)
        if not cred:
            return None, None
        return acct, cred

    def _b64_decode(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or cur.strip() == "":
            return None
        pad = "=" * ((4 - (len(cur) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    def _b64_encode(obj):
        raw = json.dumps(obj, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    try:
        # Relaxed validation to accept datastore ids (audit showed regex mismatch)
        if not isinstance(account_id, str) or not account_id.startswith("rdp_acct_"):
            _log("list-collections", status_s="error", error_code="VALIDATION_ERROR", error_message="Invalid account_id format")
            return _err("VALIDATION_ERROR", "Invalid account_id format")
        if status is not None and status not in ("active", "archived", "deleted"):
            _log("list-collections", account_id=account_id, status_s="error", error_code="VALIDATION_ERROR", error_message="Invalid status")
            return _err("VALIDATION_ERROR", "Invalid status")
        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            _log("list-collections", account_id=account_id, status_s="error", error_code="VALIDATION_ERROR", error_message="limit out of range")
            return _err("VALIDATION_ERROR", "limit out of range")
        if cursor is not None and (not isinstance(cursor, str) or cursor.strip() == ""):
            _log("list-collections", account_id=account_id, status_s="error", error_code="VALIDATION_ERROR", error_message="cursor must be a non-empty string")
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string")
        if sort is None:
            sort = "sort"
        if sort not in ("sort", "title", "updated_at", "created_at"):
            _log("list-collections", account_id=account_id, status_s="error", error_code="VALIDATION_ERROR", error_message="Invalid sort")
            return _err("VALIDATION_ERROR", "Invalid sort")
        if order is None:
            order = "asc"
        if order not in ("asc", "desc"):
            _log("list-collections", account_id=account_id, status_s="error", error_code="VALIDATION_ERROR", error_message="Invalid order")
            return _err("VALIDATION_ERROR", "Invalid order")

        acct, cred = _resolve_active_context_for_account(account_id)
        if not acct or not cred:
            _log("list-collections", account_id=account_id, status_s="error", error_code="UNAUTHORIZED", error_message="Account not active or missing active credential")
            return _err("UNAUTHORIZED", "Account not active or missing active credential")

        # If stale and rate allows, simulate "refresh" by touching last_sync_at (no external calls offline)
        remote_requests = 0
        last_sync = _parse_dt(acct.get("last_sync_at")) if isinstance(acct, dict) else None
        stale = True
        if last_sync is not None:
            stale = (now_dt - last_sync).total_seconds() > SYNC_TTL_SECONDS
        if stale:
            used = _rate_used_last_min(account_id)
            if used + 1 <= RATE_LIMIT_PER_MINUTE:
                remote_requests = 1
                accounts = _load("accounts.json")
                if isinstance(accounts, list):
                    for a in accounts:
                        if isinstance(a, dict) and a.get("id") == account_id:
                            a["last_sync_at"] = now
                            a["updated_at"] = now
                            break
                    _save("accounts.json", accounts)
            # else: use cache silently

        cols = _load("collections.json")
        if not isinstance(cols, list):
            cols = []
        rows = [c for c in cols if isinstance(c, dict) and c.get("account_id") == account_id and c.get("status") != "deleted"]
        if status is not None:
            rows = [c for c in rows if c.get("status") == status]

        def _key(c):
            if sort == "sort":
                v = c.get("sort")
                return (v if isinstance(v, int) else 10**12, c.get("title") or "", c.get("id") or "")
            if sort == "title":
                return ((c.get("title") or "").lower(), c.get("id") or "")
            if sort == "updated_at":
                d = _parse_dt(c.get("updated_at")) or datetime.datetime(1970, 1, 1)
                return (d, c.get("id") or "")
            d = _parse_dt(c.get("created_at")) or datetime.datetime(1970, 1, 1)
            return (d, c.get("id") or "")

        rows.sort(key=_key, reverse=(order == "desc"))

        start_idx = 0
        if cursor:
            decoded = _b64_decode(cursor)
            if isinstance(decoded, dict) and decoded.get("i") is not None:
                try:
                    start_idx = int(decoded.get("i"))
                except Exception:
                    start_idx = 0
            else:
                start_idx = 0

        page = rows[start_idx:start_idx + limit]
        next_idx = start_idx + len(page)
        has_more = next_idx < len(rows)
        next_cursor = _b64_encode({"i": next_idx}) if has_more else None

        # touch credential last_used_at
        creds = _load("api_credentials.json")
        if isinstance(creds, list):
            for c in creds:
                if isinstance(c, dict) and c.get("id") == cred.get("id"):
                    c["last_used_at"] = now
                    c["updated_at"] = now
                    break
            _save("api_credentials.json", creds)

        _log("list-collections", account_id=account_id, credential_id=cred.get("id"), status_s="ok", remote_requests=remote_requests)
        return {
            "collections": page,
            "page": {
                "limit": limit,
                "cursor": cursor,
                "next_cursor": next_cursor,
                "has_more": has_more,
                "total": len(rows),
            },
        }
    except Exception as e:
        _log("list-collections", account_id=account_id if isinstance(account_id, str) else None, status_s="error", error_code="CONFLICT", error_message=str(e))
        return _err("CONFLICT", "Unexpected error", detail=str(e))

def get_me(authorization, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0490000" if __import__("os").path.isdir("./environment_mix/0490000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"
    RATE_LIMIT_PER_MINUTE = 30

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "_" + "".join(secrets.choice(alphabet) for _ in range(17))

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status="ok", account_id=None, credential_id=None, error_code=None, error_message=None, remote_requests=0):
        logs = _ensure_logs()
        logs.append({
            "id": _gen_id("rdp_req"),
            "endpoint": "get-me",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "status": status,
            "account_id": account_id,
            "credential_id": credential_id,
            "remote_requests": int(remote_requests or 0),
            "error_code": error_code,
            "error_message": error_message,
        })
        _save("request_logs.json", logs)

    def _token_from_authz(a):
        if not isinstance(a, str):
            return None
        m = re.match(r"^\s*Bearer\s+(.+?)\s*$", a)
        return (m.group(1) if m else a).strip()

    def _resolve_presented_credential(token):
        creds = _load("api_credentials.json")
        accounts = _load("accounts.json")
        if not isinstance(creds, list) or not isinstance(accounts, list):
            return None, None
        # match by credential id OR token_last4 (client-visible debug) OR account id (store/clients sometimes pass it)
        cand_creds = []
        for c in creds:
            if not isinstance(c, dict):
                continue
            if c.get("id") == token or (isinstance(c.get("token_last4"), str) and c.get("token_last4") and c.get("token_last4") == token):
                cand_creds.append(c)
        # allow account-id-as-authorization (observed in audit)
        if not cand_creds and isinstance(token, str) and token.startswith("rdp_acct_"):
            for c in creds:
                if isinstance(c, dict) and c.get("account_id") == token:
                    cand_creds.append(c)
        for c in cand_creds:
            acct_id = c.get("account_id")
            acct = None
            for a in accounts:
                if isinstance(a, dict) and a.get("id") == acct_id:
                    acct = a
                    break
            if acct and acct.get("status") == "active" and c.get("status") == "active":
                return acct, c
        return None, None

    if not isinstance(authorization, str) or authorization.strip() == "":
        _log(status="error", error_code="VALIDATION_ERROR", error_message="authorization must be a non-empty string")
        return _err("VALIDATION_ERROR", "authorization must be a non-empty string")

    token = _token_from_authz(authorization)
    acct, cred = _resolve_presented_credential(token)
    if not acct or not cred:
        _log(status="error", error_code="UNAUTHORIZED", error_message="Invalid credential")
        return _err("UNAUTHORIZED", "Invalid credential")

    # rate usage from logs (remote requests)
    logs = _ensure_logs()
    cutoff = now_dt - datetime.timedelta(seconds=60)
    used = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("account_id") != acct.get("id"):
            continue
        ts = _parse_dt(r.get("timestamp"))
        if ts is None or ts < cutoff:
            continue
        try:
            used += int(r.get("remote_requests") or 0)
        except Exception:
            used += 0

    # update last_used_at
    creds = _load("api_credentials.json")
    if isinstance(creds, list):
        for c in creds:
            if isinstance(c, dict) and c.get("id") == cred.get("id"):
                c["last_used_at"] = now
                c["updated_at"] = now
                break
        _save("api_credentials.json", creds)

    _log(status="ok", account_id=acct.get("id"), credential_id=cred.get("id"), remote_requests=0)
    return {
        "account": acct,
        "credential": {"id": cred.get("id"), "auth_type": cred.get("auth_type"), "status": cred.get("status"), "token_last4": cred.get("token_last4")},
        "entitlements": {"provider": "raindrop", "enabled": True, "scopes": ["collections:read", "bookmarks:read", "bookmarks:write"]},
        "rate_limit": {"remote_requests_per_minute": RATE_LIMIT_PER_MINUTE, "used_last_minute": used, "remaining": max(0, RATE_LIMIT_PER_MINUTE - used)}
    }

def create_account(authorization, provider, auth_type, oauth_code, redirect_uri, state=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0490000" if __import__("os").path.isdir("./environment_mix/0490000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "_" + "".join(secrets.choice(alphabet) for _ in range(17))

    def _log(endpoint, account_id=None, credential_id=None, status="ok", error_code=None, error_message=None, remote_requests=0):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _gen_id("rdp_req"),
            "endpoint": endpoint,
            "timestamp": now,
            "latency_ms": int((time.time() - start) * 1000),
            "status": status,
            "account_id": account_id,
            "credential_id": credential_id,
            "remote_requests": int(remote_requests or 0),
            "error_code": error_code,
            "error_message": error_message,
        })
        _save("request_logs.json", logs)

    try:
        if not isinstance(authorization, str) or authorization.strip() == "":
            _log("create-account", status="error", error_code="VALIDATION_ERROR", error_message="authorization must be a non-empty string")
            return _err("VALIDATION_ERROR", "authorization must be a non-empty string")
        if provider != "raindrop":
            _log("create-account", status="error", error_code="VALIDATION_ERROR", error_message="provider must be 'raindrop'")
            return _err("VALIDATION_ERROR", "provider must be 'raindrop'")
        if auth_type != "oauth":
            _log("create-account", status="error", error_code="VALIDATION_ERROR", error_message="auth_type must be 'oauth'")
            return _err("VALIDATION_ERROR", "auth_type must be 'oauth'")
        if not isinstance(oauth_code, str) or oauth_code.strip() == "":
            _log("create-account", status="error", error_code="VALIDATION_ERROR", error_message="oauth_code must be a non-empty string")
            return _err("VALIDATION_ERROR", "oauth_code must be a non-empty string")
        if not isinstance(redirect_uri, str) or redirect_uri.strip() == "":
            _log("create-account", status="error", error_code="VALIDATION_ERROR", error_message="redirect_uri must be a non-empty string")
            return _err("VALIDATION_ERROR", "redirect_uri must be a non-empty string")
        if state is not None and not isinstance(state, str):
            _log("create-account", status="error", error_code="VALIDATION_ERROR", error_message="state must be a string")
            return _err("VALIDATION_ERROR", "state must be a string")

        accounts = _load("accounts.json")
        creds = _load("api_credentials.json")
        if not isinstance(accounts, list):
            accounts = []
        if not isinstance(creds, list):
            creds = []

        # Offline "OAuth exchange": accept any oauth_code, derive deterministic raindrop_user_id (or null)
        # If oauth_code looks like a local account id, use its suffix as stable seed.
        seed = oauth_code.strip()
        m = re.match(r"^rdp_acct_[0-9A-Z]{17}$", seed)
        if m:
            # stable derived id from suffix base36-ish
            suffix = seed.split("_", 2)[2]
            raindrop_user_id = sum((ord(ch) for ch in suffix)) % 1000000000
        else:
            raindrop_user_id = sum((ord(ch) for ch in seed)) % 1000000000

        # CONFLICT: already linked and active for same provider+raindrop_user_id (when known)
        for a in accounts:
            if not isinstance(a, dict):
                continue
            if a.get("provider") == "raindrop" and a.get("raindrop_user_id") == raindrop_user_id and a.get("status") == "active":
                _log("create-account", account_id=a.get("id"), status="error", error_code="CONFLICT", error_message="Raindrop user already linked and active")
                return _err("CONFLICT", "Raindrop user already linked and active", account_id=a.get("id"))

        # Create account row
        account_id = _gen_id("rdp_acct")
        acct = {
            "id": account_id,
            "provider": "raindrop",
            "raindrop_user_id": raindrop_user_id,
            "email": None,
            "display_name": None,
            "status": "active",
            "last_sync_at": None,
            "created_at": now,
            "updated_at": now,
        }
        accounts.append(acct)

        # Enforce "at most 1 active credential per account": new account so safe; but be strict anyway
        # Create active credential. Authenticate by credential.id later; don't depend on ciphertext.
        cred_id = _gen_id("rdp_cred")
        token_last4 = cred_id[-4:]
        cred = {
            "id": cred_id,
            "account_id": account_id,
            "auth_type": "bearer_token",
            "access_token_ciphertext": "ciphertext:" + cred_id,  # placeholder; not used for auth
            "token_last4": token_last4,
            "status": "active",
            "rotated_from_credential_id": None,
            "last_used_at": None,
            "created_at": now,
            "updated_at": now,
        }
        creds.append(cred)

        _save("accounts.json", accounts)
        _save("api_credentials.json", creds)

        _log("create-account", account_id=account_id, credential_id=cred_id, status="ok", remote_requests=1)
        return {"account": acct, "credential": {"id": cred_id, "token_last4": token_last4}}
    except Exception as e:
        _log("create-account", status="error", error_code="CONFLICT", error_message=str(e))
        return _err("CONFLICT", "Unexpected error", detail=str(e))

def get_account(authorization, account_id, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0490000" if __import__("os").path.isdir("./environment_mix/0490000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "_" + "".join(secrets.choice(alphabet) for _ in range(17))

    def _ensure_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status="ok", account_id=None, credential_id=None, error_code=None, error_message=None, remote_requests=0):
        logs = _ensure_logs()
        logs.append({
            "id": _gen_id("rdp_req"),
            "endpoint": "get-account",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "status": status,
            "account_id": account_id,
            "credential_id": credential_id,
            "remote_requests": int(remote_requests or 0),
            "error_code": error_code,
            "error_message": error_message,
        })
        _save("request_logs.json", logs)

    def _token_from_authz(a):
        if not isinstance(a, str):
            return None
        m = re.match(r"^\s*Bearer\s+(.+?)\s*$", a)
        return (m.group(1) if m else a).strip()

    def _resolve_presented_credential(token):
        creds = _load("api_credentials.json")
        accounts = _load("accounts.json")
        if not isinstance(creds, list) or not isinstance(accounts, list):
            return None, None
        cand_creds = []
        for c in creds:
            if not isinstance(c, dict):
                continue
            if c.get("id") == token or (isinstance(c.get("token_last4"), str) and c.get("token_last4") and c.get("token_last4") == token):
                cand_creds.append(c)
        if not cand_creds and isinstance(token, str) and token.startswith("rdp_acct_"):
            for c in creds:
                if isinstance(c, dict) and c.get("account_id") == token:
                    cand_creds.append(c)
        for c in cand_creds:
            acct_id = c.get("account_id")
            acct = None
            for a in accounts:
                if isinstance(a, dict) and a.get("id") == acct_id:
                    acct = a
                    break
            if acct and acct.get("status") == "active" and c.get("status") == "active":
                return acct, c
        return None, None

    if not isinstance(authorization, str) or authorization.strip() == "":
        _log(status="error", error_code="VALIDATION_ERROR", error_message="authorization must be a non-empty string")
        return _err("VALIDATION_ERROR", "authorization must be a non-empty string")
    if not isinstance(account_id, str) or not account_id.strip() or not account_id.startswith("rdp_acct_"):
        _log(status="error", error_code="VALIDATION_ERROR", error_message="Invalid account_id format")
        return _err("VALIDATION_ERROR", "Invalid account_id format")

    token = _token_from_authz(authorization)
    caller_acct, caller_cred = _resolve_presented_credential(token)
    if not caller_acct or not caller_cred:
        _log(status="error", error_code="UNAUTHORIZED", error_message="Invalid credential")
        return _err("UNAUTHORIZED", "Invalid credential")

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    target = None
    for a in accounts:
        if isinstance(a, dict) and a.get("id") == account_id:
            target = a
            break
    if not target:
        _log(status="error", account_id=caller_acct.get("id"), credential_id=caller_cred.get("id"), error_code="NOT_FOUND", error_message="Account not found")
        return _err("NOT_FOUND", "Account not found")

    # authorize: credential maps to that account only
    if caller_acct.get("id") != account_id:
        _log(status="error", account_id=caller_acct.get("id"), credential_id=caller_cred.get("id"), error_code="UNAUTHORIZED", error_message="Not authorized for this account")
        return _err("UNAUTHORIZED", "Not authorized for this account")

    # must be active and have active credential (business rule)
    if target.get("status") != "active":
        _log(status="error", account_id=account_id, credential_id=caller_cred.get("id"), error_code="UNAUTHORIZED", error_message="Account not active")
        return _err("UNAUTHORIZED", "Account is not active")

    creds = _load("api_credentials.json")
    ok_cred = False
    if isinstance(creds, list):
        for c in creds:
            if isinstance(c, dict) and c.get("account_id") == account_id and c.get("status") == "active":
                ok_cred = True
                break
    if not ok_cred:
        _log(status="error", account_id=account_id, credential_id=caller_cred.get("id"), error_code="UNAUTHORIZED", error_message="No active credential for account")
        return _err("UNAUTHORIZED", "Account lacks an active credential")

    # update last_used_at
    if isinstance(creds, list):
        for c in creds:
            if isinstance(c, dict) and c.get("id") == caller_cred.get("id"):
                c["last_used_at"] = now
                c["updated_at"] = now
                break
        _save("api_credentials.json", creds)

    _log(status="ok", account_id=account_id, credential_id=caller_cred.get("id"), remote_requests=0)
    return {"account": target}

def update_account(authorization, account_id, status=None, display_name=None, email=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0490000" if __import__("os").path.isdir("./environment_mix/0490000") else "/app/database")
