        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    ALLOWED_STATUSES = ("active", "error", "revoked")
    TRANSITIONS = {
        "active": set(["error", "revoked"]),
        "error": set(["active", "revoked"]),
        "revoked": set([]),
    }

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "_" + "".join(secrets.choice(alphabet) for _ in range(17))

    def _ensure_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status_s="ok", account_id=None, credential_id=None, error_code=None, error_message=None, remote_requests=0):
        logs = _ensure_logs()
        logs.append({
            "id": _gen_id("rdp_req"),
            "endpoint": "update-account",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "status": status_s,
            "account_id": account_id,
            "credential_id": credential_id,
            "remote_requests": int(remote_requests or 0),
            "error_code": error_code,
            "error_message": error_message,
        })
        _save("request_logs.json", logs)

    def _token_from_authz(a):
        if not isinstance(a, str):
            return None
        m = re.match(r"^\s*Bearer\s+(.+?)\s*$", a)
        return (m.group(1) if m else a).strip()

    def _resolve_presented_credential(token):
        creds = _load("api_credentials.json")
        accounts = _load("accounts.json")
        if not isinstance(creds, list) or not isinstance(accounts, list):
            return None, None
        cand_creds = []
        for c in creds:
            if not isinstance(c, dict):
                continue
            if c.get("id") == token or (isinstance(c.get("token_last4"), str) and c.get("token_last4") and c.get("token_last4") == token):
                cand_creds.append(c)
        if not cand_creds and isinstance(token, str) and token.startswith("rdp_acct_"):
            for c in creds:
                if isinstance(c, dict) and c.get("account_id") == token:
                    cand_creds.append(c)
        for c in cand_creds:
            acct_id = c.get("account_id")
            acct = None
            for a in accounts:
                if isinstance(a, dict) and a.get("id") == acct_id:
                    acct = a
                    break
            if acct and acct.get("status") == "active" and c.get("status") == "active":
                return acct, c
        return None, None

    if not isinstance(authorization, str) or authorization.strip() == "":
        _log(status_s="error", error_code="VALIDATION_ERROR", error_message="authorization must be a non-empty string")
        return _err("VALIDATION_ERROR", "authorization must be a non-empty string")
    if not isinstance(account_id, str) or not account_id.strip() or not account_id.startswith("rdp_acct_"):
        _log(status_s="error", error_code="VALIDATION_ERROR", error_message="Invalid account_id format")
        return _err("VALIDATION_ERROR", "Invalid account_id format")
    if status is not None and status not in ALLOWED_STATUSES:
        _log(status_s="error", account_id=account_id, error_code="VALIDATION_ERROR", error_message="Invalid status")
        return _err("VALIDATION_ERROR", "Invalid status")
    if display_name is not None and not isinstance(display_name, str):
        _log(status_s="error", account_id=account_id, error_code="VALIDATION_ERROR", error_message="display_name must be a string")
        return _err("VALIDATION_ERROR", "display_name must be a string")
    if email is not None and not isinstance(email, str):
        _log(status_s="error", account_id=account_id, error_code="VALIDATION_ERROR", error_message="email must be a string")
        return _err("VALIDATION_ERROR", "email must be a string")

    token = _token_from_authz(authorization)
    caller_acct, caller_cred = _resolve_presented_credential(token)
    if not caller_acct or not caller_cred:
        _log(status_s="error", error_code="UNAUTHORIZED", error_message="Invalid credential")
        return _err("UNAUTHORIZED", "Invalid credential")

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    idx = None
    for i, a in enumerate(accounts):
        if isinstance(a, dict) and a.get("id") == account_id:
            idx = i
            break
    if idx is None:
        _log(status_s="error", account_id=caller_acct.get("id"), credential_id=caller_cred.get("id"), error_code="NOT_FOUND", error_message="Account not found")
        return _err("NOT_FOUND", "Account not found")

    # must be authorized for this account
    if caller_acct.get("id") != account_id:
        _log(status_s="error", account_id=caller_acct.get("id"), credential_id=caller_cred.get("id"), error_code="UNAUTHORIZED", error_message="Not authorized for this account")
        return _err("UNAUTHORIZED", "Not authorized for this account")

    # enforce lifecycle transitions if status provided
    cur = accounts[idx].get("status")
    if status is not None and status != cur:
        allowed = TRANSITIONS.get(cur, set())
        if status not in allowed:
            _log(status_s="error", account_id=account_id, credential_id=caller_cred.get("id"), error_code="INVALID_TRANSITION", error_message=f"Illegal status transition {cur}->{status}")
            return _err("INVALID_TRANSITION", f"Illegal status transition {cur}->{status}")

    changed = False
    if status is not None and status != accounts[idx].get("status"):
        accounts[idx]["status"] = status
        changed = True
    if display_name is not None and display_name != accounts[idx].get("display_name"):
        accounts[idx]["display_name"] = display_name
        changed = True
    if email is not None and email != accounts[idx].get("email"):
        accounts[idx]["email"] = email
        changed = True

    if not changed:
        # idempotent: return current record, but still observable (log); no mutation needed
        _log(status_s="ok", account_id=account_id, credential_id=caller_cred.get("id"), remote_requests=0)
        return {"account": accounts[idx]}

    accounts[idx]["updated_at"] = now
    _save("accounts.json", accounts)

    # touch credential last_used_at
    creds = _load("api_credentials.json")
    if isinstance(creds, list):
        for c in creds:
            if isinstance(c, dict) and c.get("id") == caller_cred.get("id"):
                c["last_used_at"] = now
                c["updated_at"] = now
                break
        _save("api_credentials.json", creds)

    _log(status_s="ok", account_id=account_id, credential_id=caller_cred.get("id"), remote_requests=0)
    return {"account": accounts[idx]}

