        if len(url) > URL_MAX_LEN:
            _log(status_s="error", account_id=account_id, error_code="VALIDATION_ERROR", error_message=f"url exceeds maximum length {URL_MAX_LEN}")
            return _err("VALIDATION_ERROR", f"url exceeds maximum length {URL_MAX_LEN}")
    if title is not None and not isinstance(title, str):
        _log(status_s="error", account_id=account_id, error_code="VALIDATION_ERROR", error_message="title must be a string")
        return _err("VALIDATION_ERROR", "title must be a string")
    if excerpt is not None and not isinstance(excerpt, str):
        _log(status_s="error", account_id=account_id, error_code="VALIDATION_ERROR", error_message="excerpt must be a string")
        return _err("VALIDATION_ERROR", "excerpt must be a string")
    if cover_url is not None and not isinstance(cover_url, str):
        _log(status_s="error", account_id=account_id, error_code="VALIDATION_ERROR", error_message="cover_url must be a string")
        return _err("VALIDATION_ERROR", "cover_url must be a string")
    if status is not None and status not in ("draft", "creating", "active", "deleted", "error"):
        _log(status_s="error", account_id=account_id, error_code="VALIDATION_ERROR", error_message="Invalid status")
        return _err("VALIDATION_ERROR", "Invalid status")

    if tags is None:
        tags_list = None
    elif isinstance(tags, list):
        tags_list = tags
        if len(tags_list) > TAGS_MAX:
            _log(status_s="error", account_id=account_id, error_code="VALIDATION_ERROR", error_message=f"too many tags (max {TAGS_MAX})")
            return _err("VALIDATION_ERROR", f"too many tags (max {TAGS_MAX})")
        for i, tg in enumerate(tags_list):
            if not isinstance(tg, str):
                _log(status_s="error", account_id=account_id, error_code="VALIDATION_ERROR", error_message=f"tags[{i}] must be a string")
                return _err("VALIDATION_ERROR", f"tags[{i}] must be a string")
    else:
        _log(status_s="error", account_id=account_id, error_code="VALIDATION_ERROR", error_message="tags must be an array of strings")
        return _err("VALIDATION_ERROR", "tags must be an array of strings")

    token = _token_from_authz(authorization)
    caller_acct, caller_cred = _resolve_presented_credential(token)
    if not caller_acct or not caller_cred:
        _log(status_s="error", error_code="UNAUTHORIZED", error_message="Invalid credential")
        return _err("UNAUTHORIZED", "Invalid credential")
    if caller_acct.get("id") != account_id:
        _log(status_s="error", account_id=caller_acct.get("id"), credential_id=caller_cred.get("id"), error_code="UNAUTHORIZED", error_message="Not authorized for this account")
        return _err("UNAUTHORIZED", "Not authorized for this account")

    bookmarks = _load("bookmarks.json")
    if not isinstance(bookmarks, list):
        bookmarks = []
    idx = None
    for i, b in enumerate(bookmarks):
        if isinstance(b, dict) and b.get("id") == bookmark_id and b.get("account_id") == account_id:
            idx = i
            break
    if idx is None:
        _log(status_s="error", account_id=account_id, credential_id=caller_cred.get("id"), error_code="NOT_FOUND", error_message="Bookmark not found under account")
        return _err("NOT_FOUND", "Bookmark not found under account")
    if bookmarks[idx].get("status") == "deleted":
        _log(status_s="error", account_id=account_id, credential_id=caller_cred.get("id"), error_code="NOT_FOUND", error_message="Bookmark not found under account")
        return _err("NOT_FOUND", "Bookmark not found under account")

    # foreign key check for collection_id if set: must belong to same account and not be deleted
    if collection_id is not None:
        cols = _load("collections.json")
        if not isinstance(cols, list):
            cols = []
        ok = False
        for c in cols:
            if isinstance(c, dict) and c.get("id") == collection_id and c.get("account_id") == account_id and c.get("status") != "deleted":
                ok = True
                break
        if not ok:
            _log(status_s="error", account_id=account_id, credential_id=caller_cred.get("id"), error_code="NOT_FOUND", error_message="collection not found under account")
            return _err("NOT_FOUND", "Collection does not exist under that account")

    cur_status = bookmarks[idx].get("status")
    if status is not None and status != cur_status:
        allowed = TRANSITIONS.get(cur_status, set())
        if status not in allowed:
            _log(status_s="error", account_id=account_id, credential_id=caller_cred.get("id"), error_code="INVALID_TRANSITION", error_message=f"Illegal status transition {cur_status}->{status}")
            return _err("INVALID_TRANSITION", f"Illegal status transition {cur_status}->{status}")

    changed = False
    if collection_id is not None and collection_id != bookmarks[idx].get("collection_id"):
        bookmarks[idx]["collection_id"] = collection_id
        changed = True
    if url is not None and url.strip() != bookmarks[idx].get("url"):
        bookmarks[idx]["url"] = url.strip()
        changed = True
    if title is not None and title != bookmarks[idx].get("title"):
        bookmarks[idx]["title"] = title
        changed = True
    if excerpt is not None and excerpt != bookmarks[idx].get("excerpt"):
        bookmarks[idx]["excerpt"] = excerpt
        changed = True
    if tags_list is not None and tags_list != bookmarks[idx].get("tags"):
        bookmarks[idx]["tags"] = tags_list
        changed = True
    if cover_url is not None and cover_url != bookmarks[idx].get("cover_url"):
        bookmarks[idx]["cover_url"] = cover_url
        changed = True
    if status is not None and status != bookmarks[idx].get("status"):
        bookmarks[idx]["status"] = status
        if status != "error":
            bookmarks[idx]["error_message"] = None
        changed = True

    if changed:
        # refresh search_text
        t = bookmarks[idx].get("title") or ""
        e = bookmarks[idx].get("excerpt") or ""
        u = bookmarks[idx].get("url") or ""
        tg = bookmarks[idx].get("tags") or []
        try:
            tg_s = " ".join([x.strip() for x in tg if isinstance(x, str)])
        except Exception:
            tg_s = ""
        st = " ".join([x for x in [t.strip(), e.strip(), u.strip(), tg_s] if x]).strip()
        bookmarks[idx]["search_text"] = st or None
        bookmarks[idx]["updated_at"] = now
        _save("bookmarks.json", bookmarks)

    # touch credential last_used_at
    creds = _load("api_credentials.json")
    if isinstance(creds, list):
        for c in creds:
            if isinstance(c, dict) and c.get("id") == caller_cred.get("id"):
                c["last_used_at"] = now
                c["updated_at"] = now
                break
        _save("api_credentials.json", creds)

    _log(status_s="ok", account_id=account_id, credential_id=caller_cred.get("id"), remote_requests=0)
    return {"bookmark": bookmarks[idx]}
